using System;

string[] entradas = { "3", "texto", "7" };
const int objetivo = 7;
foreach (string entrada in entradas)
{
    if (!int.TryParse(entrada, out int intento))
    {
        Console.WriteLine("Ingrese un número");
        continue;
    }
    if (intento == objetivo)
    {
        Console.WriteLine("¡Acertó!");
        break;
    }
    Console.WriteLine("Siga intentando");
}

