using System;

static int Duplicar(int cantidad)
{
    int total = cantidad * 2;
    return total;
}

Console.WriteLine(Duplicar(6));

/// <summary>Calcula un total didáctico sin representar una regla tributaria real.</summary>
static decimal CalcularTotal(decimal subtotal, decimal taxRate)
{
    return subtotal * (1m + taxRate);
}

const decimal taxRate = 0.12m;
decimal total = CalcularTotal(10.005m, taxRate);
Console.WriteLine($"Mostrado: {total:F2}; valor: {total}");

using System;
using System.IO;

string path = Path.Combine(Path.GetTempPath(), $"curso-using-{Guid.NewGuid():N}.txt");
try
{
    using (StreamWriter writer = File.CreateText(path))
    {
        writer.WriteLine("bloque using");
    }

    {
        using StreamReader reader = File.OpenText(path);
        Console.WriteLine(reader.ReadLine());
    }
}
finally
{
    if (File.Exists(path)) File.Delete(path);
}

